import{_ as a,o as t,c as s,ag as i}from"./chunks/framework.DNmTgtHf.js";const u=JSON.parse('{"title":"Async Executor, Connection Pools & Graceful Shutdown","description":"","frontmatter":{},"headers":[],"relativePath":"todo/my_verify_docs/async-executor-and-shutdown.md","filePath":"todo/my_verify_docs/async-executor-and-shutdown.md"}'),o={name:"todo/my_verify_docs/async-executor-and-shutdown.md"};function n(r,e,d,l,c,h){return t(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="async-executor-connection-pools-graceful-shutdown" tabindex="-1">Async Executor, Connection Pools &amp; Graceful Shutdown <a class="header-anchor" href="#async-executor-connection-pools-graceful-shutdown" aria-label="Permalink to &quot;Async Executor, Connection Pools &amp; Graceful Shutdown&quot;">​</a></h1><h2 id="the-problem" tabindex="-1">The Problem <a class="header-anchor" href="#the-problem" aria-label="Permalink to &quot;The Problem&quot;">​</a></h2><p>During pod restarts, in-flight <code>@Async</code> audit tasks were rejected:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>RejectedExecutionException: ExecutorService in shutdown state did not accept task</span></span></code></pre></div><p>The root cause: Spring was using a single-thread <code>ThreadPoolTaskScheduler</code> (meant for <code>@Scheduled</code> cron jobs) as the executor for <code>@Async</code> methods. On SIGTERM, this scheduler shut down immediately, rejecting any pending audit submissions.</p><hr><h2 id="how-async-works-in-spring" tabindex="-1">How <code>@Async</code> Works in Spring <a class="header-anchor" href="#how-async-works-in-spring" aria-label="Permalink to &quot;How \`@Async\` Works in Spring&quot;">​</a></h2><p>When a method is annotated with <code>@Async</code>:</p><ol><li>The caller doesn&#39;t wait for the method to finish — it returns immediately</li><li>Spring submits the method body as a task to a <code>TaskExecutor</code></li><li>The task runs on a separate thread from the executor pool</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Request thread:  [--- processVerification() ---]  →  return response</span></span>
<span class="line"><span>                              |</span></span>
<span class="line"><span>                        @Async call</span></span>
<span class="line"><span>                              ↓</span></span>
<span class="line"><span>Executor thread:        [--- auditVerificationResponse() ---]  ← runs independently</span></span></code></pre></div><h3 id="executor-resolution-order" tabindex="-1">Executor Resolution Order <a class="header-anchor" href="#executor-resolution-order" aria-label="Permalink to &quot;Executor Resolution Order&quot;">​</a></h3><p>Spring&#39;s <code>@EnableAsync</code> looks for an executor in this order:</p><ol><li>A bean named <code>taskExecutor</code></li><li>A bean of type <code>TaskExecutor</code></li><li>A bean of type <code>Executor</code></li><li>Fallback: <code>SimpleAsyncTaskExecutor</code> or any available <code>TaskScheduler</code></li></ol><p>In this project, no <code>taskExecutor</code> bean existed, so Spring fell back to the <code>ThreadPoolTaskScheduler</code> (pool size 1) used for <code>@Scheduled</code> jobs.</p><hr><h2 id="the-fix-custom-taskexecutor" tabindex="-1">The Fix: Custom TaskExecutor <a class="header-anchor" href="#the-fix-custom-taskexecutor" aria-label="Permalink to &quot;The Fix: Custom TaskExecutor&quot;">​</a></h2><div class="language-java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">@</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">Bean</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">name</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;taskExecutor&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">public</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Executor </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">taskExecutor</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    ThreadPoolTaskExecutor executor </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> new</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> ThreadPoolTaskExecutor</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    executor.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">setCorePoolSize</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">4</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    executor.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">setMaxPoolSize</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">8</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    executor.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">setQueueCapacity</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">100</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    executor.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">setThreadNamePrefix</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;async-audit-&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    executor.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">setWaitForTasksToCompleteOnShutdown</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    executor.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">setAwaitTerminationSeconds</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">30</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> executor;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><h3 id="settings-explained" tabindex="-1">Settings Explained <a class="header-anchor" href="#settings-explained" aria-label="Permalink to &quot;Settings Explained&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Setting</th><th>Value</th><th>Why</th></tr></thead><tbody><tr><td><code>corePoolSize</code></td><td>4</td><td>3 <code>@Async</code> audit methods, 4 threads allows parallel execution under concurrent requests</td></tr><tr><td><code>maxPoolSize</code></td><td>8</td><td>2x core for burst handling. I/O-bound tasks (DB + S3), so more than 8 could overwhelm downstream resources</td></tr><tr><td><code>queueCapacity</code></td><td>100</td><td>Buffers ~10s of burst at 10 tasks/sec. Overflow creates threads up to maxPoolSize</td></tr><tr><td><code>threadNamePrefix</code></td><td><code>async-audit-</code></td><td>Threads appear as <code>async-audit-1</code> in logs instead of <code>scheduling-1</code></td></tr><tr><td><code>waitForTasksToCompleteOnShutdown</code></td><td><code>true</code></td><td>On SIGTERM: <code>shutdown()</code> (drain queue) instead of <code>shutdownNow()</code> (kill everything)</td></tr><tr><td><code>awaitTerminationSeconds</code></td><td>30</td><td>Safety cap — force-terminate if tasks don&#39;t finish within 30s</td></tr></tbody></table><h3 id="how-threadpooltaskexecutor-processes-tasks" tabindex="-1">How ThreadPoolTaskExecutor Processes Tasks <a class="header-anchor" href="#how-threadpooltaskexecutor-processes-tasks" aria-label="Permalink to &quot;How ThreadPoolTaskExecutor Processes Tasks&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Task submitted</span></span>
<span class="line"><span>  → Core thread available?  → YES → run immediately</span></span>
<span class="line"><span>                            → NO  → Queue has space?  → YES → queue the task</span></span>
<span class="line"><span>                                                       → NO  → Below maxPoolSize?  → YES → create new thread</span></span>
<span class="line"><span>                                                                                    → NO  → REJECT (RejectedExecutionException)</span></span></code></pre></div><h3 id="shutdown-behavior" tabindex="-1">Shutdown Behavior <a class="header-anchor" href="#shutdown-behavior" aria-label="Permalink to &quot;Shutdown Behavior&quot;">​</a></h3><p><strong>Without <code>waitForTasksToComplete</code>:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>SIGTERM → shutdownNow() → interrupt running tasks, discard queued → RejectedExecutionException</span></span></code></pre></div><p><strong>With <code>waitForTasksToComplete</code>:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>SIGTERM → shutdown() → stop accepting NEW tasks → drain running + queued → wait up to 30s → terminate</span></span></code></pre></div><hr><h2 id="thread-pools-vs-connection-pools" tabindex="-1">Thread Pools vs Connection Pools <a class="header-anchor" href="#thread-pools-vs-connection-pools" aria-label="Permalink to &quot;Thread Pools vs Connection Pools&quot;">​</a></h2><p>These are completely independent resources:</p><h3 id="thread-pool-threadpooltaskexecutor" tabindex="-1">Thread Pool (ThreadPoolTaskExecutor) <a class="header-anchor" href="#thread-pool-threadpooltaskexecutor" aria-label="Permalink to &quot;Thread Pool (ThreadPoolTaskExecutor)&quot;">​</a></h3><ul><li><strong>What it holds:</strong> Worker threads waiting for tasks</li><li><strong>Cost of idle thread:</strong> ~1MB stack memory, no I/O resources</li><li><strong>When active:</strong> Thread picks up a task, executes it, returns to pool</li><li><strong>Configured by:</strong> <code>setCorePoolSize</code>, <code>setMaxPoolSize</code></li></ul><h3 id="connection-pool-hikaricp" tabindex="-1">Connection Pool (HikariCP) <a class="header-anchor" href="#connection-pool-hikaricp" aria-label="Permalink to &quot;Connection Pool (HikariCP)&quot;">​</a></h3><ul><li><strong>What it holds:</strong> Open JDBC connections to MySQL</li><li><strong>Cost of idle connection:</strong> Open TCP socket + MySQL session (~3-5MB on MySQL side)</li><li><strong>When active:</strong> Thread borrows a connection, runs queries, returns it to pool</li><li><strong>Configured by:</strong> <code>spring.datasource.hikari.maximum-pool-size</code> (default: 10)</li></ul><h3 id="how-they-interact" tabindex="-1">How They Interact <a class="header-anchor" href="#how-they-interact" aria-label="Permalink to &quot;How They Interact&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Idle thread:     [waiting...]   → no connection held</span></span>
<span class="line"><span>Task arrives:    [get connection from HikariCP] → [run queries] → [return connection] → [waiting...]</span></span></code></pre></div><p>A thread only holds a DB connection during query/transaction execution. Idle threads consume zero DB connections.</p><h3 id="current-pool-sizes-in-this-project" tabindex="-1">Current Pool Sizes in This Project <a class="header-anchor" href="#current-pool-sizes-in-this-project" aria-label="Permalink to &quot;Current Pool Sizes in This Project&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Pool</th><th>Size</th><th>Source</th></tr></thead><tbody><tr><td>Stage executor threads</td><td>16</td><td><code>myservice.api.vida.thread.pool.size=16</code></td></tr><tr><td>Async audit threads</td><td>4-8</td><td><code>TaskExecutor</code> bean (new)</td></tr><tr><td>Scheduler threads</td><td>1</td><td>Spring default <code>ThreadPoolTaskScheduler</code></td></tr><tr><td>DB connections (HikariCP)</td><td>10</td><td>Spring Boot default</td></tr><tr><td>Request threads (Undertow)</td><td>~varies</td><td>Undertow I/O threads (typically cores x 8)</td></tr></tbody></table><p>Under peak load, 16 stage threads + 8 audit threads + request threads could all compete for 10 DB connections. HikariCP queues the overflow (waits up to 30s). This hasn&#39;t been an issue in production, but if DB connection timeouts appear, consider increasing <code>spring.datasource.hikari.maximum-pool-size</code>.</p><hr><h2 id="graceful-shutdown" tabindex="-1">Graceful Shutdown <a class="header-anchor" href="#graceful-shutdown" aria-label="Permalink to &quot;Graceful Shutdown&quot;">​</a></h2><h3 id="what-it-does" tabindex="-1">What It Does <a class="header-anchor" href="#what-it-does" aria-label="Permalink to &quot;What It Does&quot;">​</a></h3><div class="language-properties vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">properties</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">server.shutdown</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=graceful</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">spring.lifecycle.timeout-per-shutdown-phase</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=30s</span></span></code></pre></div><p>On SIGTERM:</p><ol><li>Web server stops accepting <strong>new</strong> HTTP requests (returns 503)</li><li>Waits for <strong>in-flight</strong> requests to complete (up to timeout)</li><li>Then proceeds with bean destruction</li></ol><h3 id="why-we-didn-t-add-it" tabindex="-1">Why We Didn&#39;t Add It <a class="header-anchor" href="#why-we-didn-t-add-it" aria-label="Permalink to &quot;Why We Didn&#39;t Add It&quot;">​</a></h3><p>The K8s deployment already handles traffic routing — new pods spin up first, traffic shifts to them, THEN old pods get SIGTERM. By the time SIGTERM arrives, no new requests hit the old pod.</p><p>The only concern is <code>@Async</code> tasks that were already submitted but haven&#39;t finished. <code>setWaitForTasksToCompleteOnShutdown(true)</code> handles that directly at the executor level.</p><p>If K8s traffic routing ever changes, or if there are edge cases where requests arrive during shutdown, <code>server.shutdown=graceful</code> can be re-added as defense-in-depth.</p><hr><h2 id="topics-for-further-reading" tabindex="-1">Topics for Further Reading <a class="header-anchor" href="#topics-for-further-reading" aria-label="Permalink to &quot;Topics for Further Reading&quot;">​</a></h2><h3 id="thread-pool-internals" tabindex="-1">Thread Pool Internals <a class="header-anchor" href="#thread-pool-internals" aria-label="Permalink to &quot;Thread Pool Internals&quot;">​</a></h3><ul><li>Java <code>ThreadPoolExecutor</code> — core/max/queue interaction, rejection policies (<code>AbortPolicy</code>, <code>CallerRunsPolicy</code>)</li><li><code>ForkJoinPool</code> vs <code>ThreadPoolExecutor</code> — when to use which</li><li>Virtual threads (Java 21) — <code>Executors.newVirtualThreadPerTaskExecutor()</code>, how they change the threading model</li></ul><h3 id="connection-pool-internals" tabindex="-1">Connection Pool Internals <a class="header-anchor" href="#connection-pool-internals" aria-label="Permalink to &quot;Connection Pool Internals&quot;">​</a></h3><ul><li>HikariCP configuration — <code>maximumPoolSize</code>, <code>minimumIdle</code>, <code>connectionTimeout</code>, <code>leakDetectionThreshold</code></li><li>Connection pool sizing formula: <code>connections = (core_count * 2) + effective_spindle_count</code> (from HikariCP wiki)</li><li>How <code>@Transactional</code> interacts with connection checkout/return</li><li>Connection leak detection — <code>spring.datasource.hikari.leak-detection-threshold</code></li></ul><h3 id="spring-transaction-management" tabindex="-1">Spring Transaction Management <a class="header-anchor" href="#spring-transaction-management" aria-label="Permalink to &quot;Spring Transaction Management&quot;">​</a></h3><ul><li><code>@Transactional</code> propagation types — <code>REQUIRED</code>, <code>REQUIRES_NEW</code>, <code>NESTED</code></li><li>The inner-transaction rollback-only problem (what caused the liveness bug)</li><li>Spring proxy self-invocation limitation — why <code>@Transactional</code> doesn&#39;t work on private or self-called methods</li><li><code>TransactionTemplate</code> as an alternative to declarative <code>@Transactional</code></li></ul><h3 id="spring-async" tabindex="-1">Spring Async <a class="header-anchor" href="#spring-async" aria-label="Permalink to &quot;Spring Async&quot;">​</a></h3><ul><li><code>@Async</code> with return types — <code>CompletableFuture&lt;T&gt;</code> for async results</li><li><code>AsyncConfigurer</code> interface — custom exception handling for async methods</li><li><code>@Async</code> + <code>@Transactional</code> interaction — each async method gets its own transaction</li><li><code>CompletableFuture</code> composition — <code>thenCompose</code>, <code>allOf</code>, <code>handle</code> (used in stage executor)</li></ul><h3 id="monitoring-observability" tabindex="-1">Monitoring &amp; Observability <a class="header-anchor" href="#monitoring-observability" aria-label="Permalink to &quot;Monitoring &amp; Observability&quot;">​</a></h3><ul><li>Micrometer metrics — <code>@Timed</code>, custom counters, gauges</li><li>HikariCP metrics — <code>hikaricp.connections.active</code>, <code>hikaricp.connections.pending</code></li><li>Thread pool metrics — active count, queue size, completed task count</li><li>Prometheus + Grafana setup for Spring Boot Actuator</li></ul>`,61)])])}const k=a(o,[["render",n]]);export{u as __pageData,k as default};
